ALTER TABLE public.at_home_pack_items ADD COLUMN backstory text, ADD COLUMN search_keywords text[]; UPDATE public.at_home_pack_items SET backstory='A window into the traditions, daily life and creativity of this place.',search_keywords=ARRAY[pack||' culture',pack||' traditions']; UPDATE public.at_home_pack_items SET title='Festival Colors',body='Look for festival colors and patterns from Thailand, then wear a color you love.' WHERE id=7; UPDATE public.at_home_pack_items SET title='Snack swap: Thai iced tea',body='Share a non-alcoholic Thai iced tea or coconut water on the call.',alt=NULL,adult=false WHERE id=11; UPDATE public.at_home_pack_items SET title='Snack swap: limeade',body='Start with a virgin limeade; approved 21+ adults can sip or skip an optional alternative.',alt='Virgin limeade',adult=true WHERE id=29; UPDATE public.at_home_pack_items SET body='How would you respectfully make an ofrenda for someone you admire?' WHERE id=33; UPDATE public.weekly_question_pool SET prompt=CASE id WHEN 33 THEN 'What quiet skill are you proud you learned?' WHEN 35 THEN 'What is a surprisingly useful travel habit you learned the hard way?' WHEN 36 THEN 'What small ritual should the squad start on this trip?' WHEN 38 THEN 'What is a brave but kind moment you remember from a trip?' ELSE prompt END WHERE id IN (33,35,36,38); UPDATE public.security_missions SET title='Festival Colors',text='Research colors and patterns seen in a festival in {destination}. Explain one meaning in a 1-minute presentation.' WHERE kind='checkin' AND title='Costume Check'; UPDATE public.game_cards SET prompt=CASE WHEN prompt ILIKE '%make a whole afternoon out of%' THEN replace(prompt,'make a whole afternoon out of','get the squad curious about') WHEN prompt ILIKE '%most overrated travel habit deserves a place on every itinerary%' THEN replace(prompt,'most overrated travel habit deserves a place on every itinerary','travel habit you would gladly leave behind') WHEN prompt ILIKE '%memorable night out%' THEN replace(prompt,'a memorable night out','a surprising change of plans') WHEN prompt ILIKE '%dance until sunrise%' THEN replace(prompt,'dance until sunrise','learn one more dance step') WHEN prompt ILIKE '%stayed out past sunrise%' THEN replace(prompt,'stayed out past sunrise','learned a new skill on a trip') WHEN prompt ILIKE '%afterparty%' THEN replace(prompt,'the afterparty is better than the party','the unscheduled moment is better than the itinerary') ELSE prompt END WHERE trip_id IS NULL AND (prompt ILIKE '%make a whole afternoon out of%' OR prompt ILIKE '%most overrated travel habit deserves a place on every itinerary%' OR prompt ILIKE '%memorable night out%' OR prompt ILIKE '%dance until sunrise%' OR prompt ILIKE '%stayed out past sunrise%' OR prompt ILIKE '%afterparty%');